// scripts/verify-knowledge-structure.mjs
//
// `docs/knowledge/` is two trees, and this is the gate that keeps them apart.
//
//   harvested/  what the source documents say. Generated by `knowledge-harvest`,
//               never hand-edited.
//   notes/      what the implementation found. Hand-written, role `review`, a
//               manual `sha:` marker, and it outranks the harvested entry it
//               names.
//
// Why a gate rather than a convention: a `<sub>` sha digests the WHOLE source
// file, not the entry, so every entry harvested from one file carries the same
// value and an edit to an entry's text does not change it. The next harvest
// cannot see the edit — it regenerates the original text or writes a duplicate.
// Hand-written knowledge under `harvested/` is therefore not just untidy, it is
// scheduled for silent deletion. The three rules below are the smallest set
// that catches it, and none of them needs a file outside the repository.
//
// Structural only. It says nothing about whether an entry is TRUE — that is
// what the drift check (`bun run knowledge:drift`) and a re-harvest are for.
import {readFileSync, readdirSync} from 'node:fs';
import {dirname, join, normalize} from 'node:path';
import {fileURLToPath} from 'node:url';

import {
  ROLES,
  derivePrefixes,
  entryLocation,
  loadCanonicalIds,
  loadCorpus,
} from './knowledge.mjs';

// The roles a harvested entry may carry: everything but `review`, which is the
// notes tree's. Derived from the CLI's list so a new role is a one-line change
// there, not two.
const HARVESTED_ROLES = ROLES.filter(role => role !== 'review');

// Below this the corpus is not small, it is broken — a parse that silently
// yields nothing (a CRLF topic file, a moved directory) would otherwise let this
// gate print OK over an empty tree, which is worse than failing. The floor is
// deliberately far below the real count (1457) so ordinary editing never trips
// it.
const MIN_HARVESTED_ENTRIES = 1000;

const repoRoot = fileURLToPath(new URL('..', import.meta.url));
const knowledgeDir = join(repoRoot, 'docs', 'knowledge');
const sourcesPath = join(
  repoRoot,
  'docs',
  'knowledge',
  'harvested',
  'SOURCES.md',
);

const SOURCE_ROW = /^\|\s*`([^`]+)`\s*\|/;
// A `<sub>` source is `path/to/file.md:12-18`, `…:12`, or a bare path.
const LINE_SUFFIX = /:[\d,-]+$/;

// The three source roots are not hardcoded: they are the directories the
// harvest manifest itself names. One of them is an absolute path on the harvest
// machine (the styleguide is a sibling repository), so hardcoding it would make
// this gate machine-specific — and deriving it means a fourth root is a
// SOURCES.md edit, reviewable in the same diff as the entries that use it.
function sourceRoots(text) {
  const roots = new Set();
  for (const line of text.split('\n')) {
    const match = SOURCE_ROW.exec(line);
    if (match) roots.add(dirname(match[1]));
  }
  if (roots.size === 0) {
    throw new Error(
      `parsed zero source rows out of ${sourcesPath}; its table format changed ` +
        'and the allowlist of source roots cannot be derived',
    );
  }

  // One row at a root's parent would widen the allowlist to everything beneath
  // it — a future `docs/open-items.md` row makes `docs` a root, and then every
  // `docs/work/...` citation passes. Refuse rather than silently widen.
  const sorted = [...roots].sort();
  for (const root of sorted) {
    const swallowed = sorted.find(
      other => other !== root && other.startsWith(`${root}/`),
    );
    if (swallowed !== undefined) {
      throw new Error(
        `${sourcesPath} derives the source root '${root}', which contains ` +
          `'${swallowed}'. A root that contains another admits everything ` +
          'beneath it; list sources at one level, not two.',
      );
    }
  }
  return sorted;
}

// `normalize` first: a `..` segment makes a string prefix test meaningless, and
// the point of this check is where the path actually lands.
function isUnderRoot(source, roots) {
  const path = normalize(source.replace(LINE_SUFFIX, ''));
  return roots.some(root => path.startsWith(`${normalize(root)}/`));
}

// Returns one line per violation, empty when the trees are clean.
function structuralViolations(entries, roots) {
  const violations = [];
  for (const entry of entries) {
    if (entry.origin !== 'harvested') continue;
    const at = `${entryLocation(entry)} (${entry.section})`;

    if (entry.roles.includes('review')) {
      violations.push(
        `${at}: role \`review\` under harvested/. A review-role entry is ` +
          'hand-written knowledge; move it to docs/knowledge/notes/.',
      );
    }
    // `review` is the label an honest hand edit wears. An invented role is what
    // a careless one wears, and it used to pass every rule here.
    for (const role of entry.roles) {
      if (role === 'review' || HARVESTED_ROLES.includes(role)) continue;
      violations.push(
        `${at}: role \`${role}\` under harvested/, which is not one of ` +
          `${HARVESTED_ROLES.join(', ')}. A harvested entry carries the role of ` +
          'the document it came from.',
      );
    }
    // The per-source loop below iterates zero times on an entry with no
    // provenance line at all, so the strongest rule here never ran on the one
    // shape a hand-written bullet is most likely to have.
    if (entry.sources.length === 0) {
      violations.push(
        `${at}: no source. Every harvested entry carries a \`<sub>\` naming ` +
          'the document it came from; a bullet without one was written by hand.',
      );
    }
    if (entry.section === 'Superseded') {
      violations.push(
        `${at}: a Superseded entry under harvested/. Superseding is a ` +
          'judgement the implementation made; it belongs in docs/knowledge/notes/.',
      );
    }
    for (const source of entry.sources) {
      if (isUnderRoot(source, roots)) continue;
      violations.push(
        `${at}: cites \`${source}\`, which is under none of the harvested ` +
          `source roots (${roots.join(', ')}). Only a harvest of those roots ` +
          'belongs in harvested/.',
      );
    }
  }
  return violations;
}

// A fourth rule, beyond the three the trees themselves imply, because the
// accident it catches is silent: `knowledge-harvest` defaults its `--corpus` to
// `<cwd>/docs/knowledge/`, so a run that forgets `--corpus docs/knowledge/harvested`
// writes a third copy of the corpus at the root. No query reads it — the CLI
// walks harvested/ and notes/ — so the knowledge is not wrong, it is invisible.
function strayTopicFiles(dir = knowledgeDir) {
  return readdirSync(dir, {withFileTypes: true})
    .filter(
      entry =>
        entry.isFile() &&
        entry.name.endsWith('.md') &&
        entry.name !== 'README.md',
    )
    .map(
      entry =>
        `docs/knowledge/${entry.name}: a topic file at the root of ` +
        'docs/knowledge/, which is neither tree — no query reads it. Move it ' +
        'into harvested/ or notes/. (A `knowledge-harvest` run without ' +
        '`--corpus docs/knowledge/harvested` writes here.)',
    );
}

// The mirror of rule 1, and fatal for the same reason rather than advisory: a
// note that does not say `review` reads, in a query result, exactly as though a
// source document had said it — and a warning inside a step that exits 0 is
// invisible in a green log.
function noteViolations(entries) {
  return entries
    .filter(entry => entry.origin === 'note' && !entry.roles.includes('review'))
    .map(
      entry =>
        `${entryLocation(entry)}: a note whose role is ` +
        `\`${entry.role ?? 'none'}\`, not \`review\`. A note states what the ` +
        'implementation found; that is what the role says.',
    );
}

// The scripts here wrap-and-rethrow with `{cause}`; printing only the outer
// message throws away the half that says which file.
function formatCauses(error) {
  const messages = [];
  for (let current = error; current; current = current.cause) {
    messages.push(current.message);
  }
  return messages.join('\n  caused by: ');
}

function main() {
  const roots = sourceRoots(readFileSync(sourcesPath, 'utf8'));
  const entries = loadCorpus(derivePrefixes(loadCanonicalIds()));
  const violations = [
    ...structuralViolations(entries, roots),
    ...noteViolations(entries),
    ...strayTopicFiles(),
  ];

  const harvested = entries.filter(entry => entry.origin === 'harvested');
  if (harvested.length < MIN_HARVESTED_ENTRIES) {
    throw new Error(
      `only ${harvested.length} harvested entries parsed, below the floor of ` +
        `${MIN_HARVESTED_ENTRIES}. The corpus did not shrink by hand — a parse ` +
        'is failing (a CRLF or BOM topic file, a moved directory), and every ' +
        'rule below would pass vacuously over the hole.',
    );
  }

  if (violations.length > 0) {
    for (const violation of violations) {
      process.stderr.write(`knowledge-structure violation: ${violation}\n`);
    }
    process.stderr.write(
      `${violations.length} violation(s). docs/knowledge/harvested/ carries ` +
        'only harvested entries; hand-written knowledge lives in ' +
        'docs/knowledge/notes/ with role `review` and a manual sha marker.\n',
    );
    return 1;
  }

  const notes = entries.length - harvested.length;
  process.stdout.write(
    `knowledge structure OK: ${harvested.length} harvested entries, each with ` +
      `a source under one of ${roots.length} roots and a role among ` +
      `${HARVESTED_ROLES.join('/')}, none Superseded; ${notes} notes, all ` +
      'review-role; nothing stranded at the root.\n',
  );
  return 0;
}

export {sourceRoots, structuralViolations, noteViolations, strayTopicFiles};

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  try {
    process.exitCode = main();
  } catch (error) {
    process.stderr.write(`${formatCauses(error)}\n`);
    process.exitCode = 2;
  }
}
